#!/usr/bin/env python3
"""Explanation in code is capped at ONE line; the rest belongs in .github/AGENTS.d/ - design and each exemption's rationale live in 010-explanation-in-code-is-capped-at-one-line.md, not here."""

from __future__ import annotations

import argparse
import ast
import io
import json
import re
import subprocess
import sys
import tokenize
from pathlib import Path

REPO_ROOT = Path(__file__).resolve().parents[2]
BASELINE_PATH = REPO_ROOT / ".github" / "one-line-comment-baseline.json"

SCANNED_SUFFIXES = (".py", ".yml", ".yaml")
SKIP_PREFIXES: tuple[str, ...] = ()

PRAGMAS: tuple[str, ...] = (
    "noqa",
    "type: ignore",
    "pragma:",
    "ruff:",
    "mypy:",
    "nosec",
    "fmt:",
    "DO NOT EDIT",
    "AUTO-GENERATED",
    "SPDX-",
    "Copyright",
    "!/usr/bin",
    "-*- coding",
    "/// script",
)

GENERATED_MARKERS = re.compile(
    r"DO NOT EDIT|AUTO-?GENERATED|GENERATED by |@generated", re.IGNORECASE
)


def is_skipped(path: str) -> bool:
    """True when `path` is exempt by prefix."""
    return any(path.startswith(p) for p in SKIP_PREFIXES)


def is_generated(text: str) -> bool:
    """True when the first 40 lines claim the file is generated."""
    return bool(GENERATED_MARKERS.search("\n".join(text.split("\n")[:40])))


def has_pragma(lines: list[str]) -> bool:
    """True when any line in the run carries a tooling pragma."""
    return any(p in line for line in lines for p in PRAGMAS)


def python_violations(text: str) -> list[tuple[int, str]]:
    """Multi-line docstrings and multi-line standalone comment runs."""
    out: list[tuple[int, str]] = []
    try:
        tree = ast.parse(text)
    except SyntaxError:
        return out
    for node in ast.walk(tree):
        if not isinstance(node, (ast.Module, ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)):
            continue
        body = node.body
        if not body:
            continue
        first = body[0]
        if not (
            isinstance(first, ast.Expr)
            and isinstance(first.value, ast.Constant)
            and isinstance(first.value.value, str)
        ):
            continue
        span = first.end_lineno - first.lineno + 1
        if span > 1:
            name = getattr(node, "name", "<module>")
            out.append((first.lineno, f"docstring spans {span} lines ({name})"))

    lines = text.split("\n")
    try:
        toks = list(tokenize.generate_tokens(io.StringIO(text).readline))
    except (tokenize.TokenError, SyntaxError, IndentationError):
        return out
    standalone = sorted(
        t.start[0]
        for t in toks
        if t.type == tokenize.COMMENT and not lines[t.start[0] - 1][: t.start[1]].strip()
    )
    out.extend(_runs(standalone, lines))
    return out


BLOCK_SCALAR_RE = re.compile(r"^(\s*)\S.*:\s*[|>][+\-0-9]*\s*(#.*)?$")


def yaml_violations(text: str) -> list[tuple[int, str]]:
    """Multi-line standalone `#` comment runs, skipping block-scalar bodies (`run: |`, `description: >`) where `#` is literal content, not a YAML comment."""
    out: list[tuple[int, str]] = []
    lines = text.split("\n")
    standalone: list[int] = []
    in_block = False
    block_parent_indent = 0
    for i, raw in enumerate(lines, start=1):
        if in_block:
            stripped = raw.strip()
            indent = len(raw) - len(raw.lstrip(" "))
            if stripped == "" or indent > block_parent_indent:
                continue
            in_block = False
        m = BLOCK_SCALAR_RE.match(raw)
        if m:
            block_parent_indent = len(m.group(1))
            in_block = True
            continue
        if raw.strip().startswith("#"):
            standalone.append(i)
    out.extend(_runs(standalone, lines))
    return out


def _runs(linenos: list[int], lines: list[str]) -> list[tuple[int, str]]:
    """Consecutive comment lines grouped into runs longer than one line."""
    out: list[tuple[int, str]] = []
    run: list[int] = []

    def flush() -> None:
        if len(run) > 1 and not has_pragma([lines[k - 1] for k in run]):
            out.append((run[0], f"comment run spans {len(run)} lines"))

    for n in linenos:
        if run and n == run[-1] + 1:
            run.append(n)
            continue
        flush()
        run = [n]
    flush()
    return out


def scan(paths: list[str]) -> dict[str, list[tuple[int, str]]]:
    """Violations per path, skipping exempt and generated files."""
    found: dict[str, list[tuple[int, str]]] = {}
    for rel in paths:
        if is_skipped(rel) or not rel.endswith(SCANNED_SUFFIXES):
            continue
        full = REPO_ROOT / rel
        if not full.is_file():
            continue
        try:
            text = full.read_text(encoding="utf-8", errors="replace")
        except OSError:
            continue
        if is_generated(text):
            continue
        hits = python_violations(text) if rel.endswith(".py") else yaml_violations(text)
        if hits:
            found[rel] = hits
    return found


def all_source_paths() -> list[str]:
    """Every tracked .py/.yml/.yaml path."""
    out = subprocess.run(
        ["git", "ls-files", "*.py", "*.yml", "*.yaml"],
        cwd=REPO_ROOT,
        capture_output=True,
        text=True,
        check=False,
    ).stdout
    return [p for p in out.split("\n") if p]


def _regressions(counts: dict[str, int], baseline: dict[str, int], found: dict) -> list[str]:
    """Lines describing every path whose count exceeds its baselined allowance."""
    out: list[str] = []
    for path, n in sorted(counts.items()):
        allowed = baseline.get(path, 0)
        if n > allowed:
            out.append(f"  {path}: {n} > {allowed} allowed")
            for lineno, why in found[path][:4]:
                out.append(f"      {path}:{lineno}  {why}")
    return out


def main() -> int:
    ap = argparse.ArgumentParser(description=__doc__)
    ap.add_argument("--write-baseline", action="store_true")
    ap.add_argument("files", nargs="*")
    args = ap.parse_args()

    paths = args.files or all_source_paths()
    scanned = [p for p in paths if p.endswith(SCANNED_SUFFIXES) and not is_skipped(p)]
    if not scanned:
        print("one-line-comments: no scannable file matched - refusing to pass vacuously")
        return 1
    found = scan(paths)
    counts = {p: len(v) for p, v in found.items()}

    if args.write_baseline:
        BASELINE_PATH.write_text(
            json.dumps({"files": dict(sorted(counts.items()))}, indent=2) + "\n",
            encoding="utf-8",
        )
        print(
            f"one-line-comments: baseline written - {len(counts)} file(s), "
            f"{sum(counts.values())} violation(s) grandfathered."
        )
        return 0

    if not BASELINE_PATH.exists():
        print(f"one-line-comments: missing baseline at {BASELINE_PATH}.", file=sys.stderr)
        print("Generate it once with: --write-baseline", file=sys.stderr)
        return 2

    baseline = json.loads(BASELINE_PATH.read_text(encoding="utf-8")).get("files", {})
    regressions = _regressions(counts, baseline, found)

    py_scanned = len([p for p in scanned if p.endswith(".py")])
    yaml_scanned = len(scanned) - py_scanned
    if regressions:
        print("one-line-comments: explanation in code is capped at ONE line.\n")
        print("\n".join(regressions))
        print(
            "\nA module, class or function gets a one-line docstring or none, and a run of\n"
            "standalone comments is one line. Move the rest into a .github/AGENTS.d/ rule.\n"
            "The baseline grandfathers what exists and may only SHRINK - it is never a\n"
            "place to park a new violation.\n"
            f"\nScanned {py_scanned} python file(s), {yaml_scanned} yaml file(s). "
            f"Baseline: {BASELINE_PATH.relative_to(REPO_ROOT)}"
        )
        return 1

    total, baseline_total = sum(counts.values()), sum(baseline.values())
    print(
        f"one-line-comments: OK - {py_scanned} python + {yaml_scanned} yaml file(s) scanned, "
        f"{total} baselined violation(s) remaining (baseline {baseline_total})."
    )
    if total < baseline_total:
        print(
            "  A count went DOWN. Refresh the baseline so it cannot creep back: "
            "python3 .github/scripts/check_one_line_comments.py --write-baseline"
        )
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
